SELECT count(*), count(id), sum(id), total(id), avg(id), min(id), max(id), count(DISTINCT id) FROM t1 WHERE NOT NOT id;
SELECT id, count(*), group_concat(id) FROM (SELECT * FROM t1 ORDER BY id) GROUP BY id HAVING count(*) > 0 ORDER BY id;
CREATE INDEX IF NOT EXISTS i45 ON t0(id DESC, id);
SELECT id, id FROM t0 WHERE id <= x'bb' ORDER BY id, id;
SELECT count(*) FROM t0 INDEXED BY i45 WHERE id IS NOT NULL;
REINDEX t0;
DROP INDEX IF EXISTS i45;
